function createMockTextDocument(uri, text, languageId) {
  const lineStarts = [0];
  const lineEnds = [];
  for (let i = 0; i < text.length; i++) {
    const ch = text.charCodeAt(i);
    if (ch === 13 || ch === 10) {
      lineEnds.push(i);
      if (ch === 13 && i + 1 < text.length && text.charCodeAt(i + 1) === 10) {
        i++;
      }
      lineStarts.push(i + 1);
    }
  }
  lineEnds.push(text.length);
  const lines = lineStarts.map((start, idx) => text.slice(start, lineEnds[idx]));
  const ext = path.extname(uri.fsPath).toLowerCase();
  const inferredLang =
    languageId ??
    (ext === '.cs'
      ? 'csharp'
      : ext === '.shader' || ext === '.cginc' || ext === '.hlsl' || ext === '.hlsli'
      ? 'unity-shaderlab'
      : 'plaintext');

  const offsetAt = (pos) => {
    if (pos.line < 0) return 0;
    if (pos.line >= lineStarts.length) return text.length;
    const start = lineStarts[pos.line];
    const end = lineEnds[pos.line];
    return Math.max(start, Math.min(end, start + pos.character));
  };

  const positionAt = (offset) => {
    const clamped = Math.max(0, Math.min(offset, text.length));
    let low = 0;
    let high = lineStarts.length;
    while (low < high) {
      const mid = Math.floor((low + high) / 2);
      if (lineStarts[mid] > clamped) high = mid;
      else low = mid + 1;
    }
    const lineIdx = Math.max(0, low - 1);
    return new Position(lineIdx, Math.min(clamped - lineStarts[lineIdx], lineEnds[lineIdx] - lineStarts[lineIdx]));
  };

  return {
    uri,
    fileName: uri.fsPath,
    languageId: inferredLang,
    version: 1,
    isDirty: false,
    isUntitled: false,
    lineCount: lines.length,
    getText: (range) => {
      if (!range) return text;
      return text.slice(offsetAt(range.start), offsetAt(range.end));
    },
    lineAt: (lineOrPos) => {
      const idx = typeof lineOrPos === 'number' ? lineOrPos : lineOrPos.line;
      const lineText = lines[idx] ?? '';
      return {
        lineNumber: idx,
        text: lineText,
        range: new Range(idx, 0, idx, lineText.length),
        firstNonWhitespaceCharacterIndex: lineText.search(/\S|$/),
        isEmptyOrWhitespace: lineText.trim().length === 0,
      };
    },
    offsetAt,
    positionAt,
    getWordRangeAtPosition: (pos, regex = /[A-Za-z0-9_]+/) => {
      const lineText = lines[pos.line] ?? '';
      const flags = regex.flags.includes('g') ? regex.flags : `${regex.flags}g`;
      const re = new RegExp(regex.source, flags);
      let m;
      while ((m = re.exec(lineText)) !== null) {
        if (pos.character >= m.index && pos.character <= m.index + m[0].length) {
          return new Range(pos.line, m.index, pos.line, m.index + m[0].length);
        }
      }
      return undefined;
    },
    save: async () => true,
  };
}

function globToRegex(glob) {
  let out = '';
  const src = glob.replace(/\\/g, '/');
  for (let i = 0; i < src.length; i++) {
    const ch = src[i];
    if (ch === '{') {
      const closeIdx = src.indexOf('}', i + 1);
      if (closeIdx > i) {
        const alts = src
          .slice(i + 1, closeIdx)
          .split(',')
          .map((a) => a.replace(/[.+^${}()|[\]\\]/g, '\\$&'));
        out += `(?:${alts.join('|')})`;
        i = closeIdx;
        continue;
      }
    }
    if (ch === '*' && src[i + 1] === '*') {
      if (src[i + 2] === '/') {
        out += '(?:.*/)?';
        i += 2;
      } else {
        out += '.*';
        i += 1;
      }
      continue;
    }
    if (ch === '*') {
      out += '[^/]*';
      continue;
    }
    if (ch === '?') {
      out += '[^/]';
      continue;
    }
    if (/[.+^${}()|[\]\\]/.test(ch)) {
      out += `\\${ch}`;
      continue;
    }
    out += ch;
  }
  return new RegExp(`^${out}$`, 'i');
}

function walkFiles(dir, result = []) {
  if (!fs.existsSync(dir)) return result;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      walkFiles(full, result);
    } else if (entry.isFile()) {
      result.push(full);
    }
  }
  return result;
}

export const workspace = {
  workspaceFolders: [],
  textDocuments: [],
  fs: {
    readFile: async (uri) => fs.promises.readFile(uri.fsPath),
    writeFile: async (uri, content) => {
      await fs.promises.mkdir(path.dirname(uri.fsPath), { recursive: true });
      await fs.promises.writeFile(uri.fsPath, content);
    },
    stat: async (uri) => {
      const st = await fs.promises.stat(uri.fsPath);
      return {
        type: st.isDirectory() ? FileType.Directory : st.isFile() ? FileType.File : FileType.Unknown,
        ctime: st.ctimeMs,
        mtime: st.mtimeMs,
        size: st.size,
      };
    },
    delete: async (uri, options = {}) => {
      await fs.promises.rm(uri.fsPath, {
        recursive: Boolean(options.recursive),
        force: true,
      });
    },
    rename: async (source, target, options = {}) => {
      if (!options.overwrite && fs.existsSync(target.fsPath)) {
        throw new Error(`Target already exists: ${target.fsPath}`);
      }
      await fs.promises.mkdir(path.dirname(target.fsPath), { recursive: true });
      await fs.promises.rename(source.fsPath, target.fsPath);
    },
    readDirectory: async (uri) => {
      const entries = await fs.promises.readdir(uri.fsPath, { withFileTypes: true });
      return entries.map((e) => [
        e.name,
        e.isDirectory() ? FileType.Directory : e.isFile() ? FileType.File : FileType.Unknown,
      ]);
    },
  },
  findFiles: async (include, exclude) => {
    const baseDir =
      typeof include === 'object' && include !== null && 'baseUri' in include
        ? include.baseUri.fsPath
        : workspace.workspaceFolders?.[0]?.uri?.fsPath ?? process.cwd();
    const pattern = typeof include === 'string' ? include : include.pattern;
    const includeRe = globToRegex(pattern);
    const excludeRe = exclude ? globToRegex(typeof exclude === 'string' ? exclude : exclude.pattern) : null;
    const files = walkFiles(baseDir);
    const uris = [];
    for (const filePath of files) {
      const rel = path.relative(baseDir, filePath).replace(/\\/g, '/');
      if (includeRe.test(rel) && (!excludeRe || !excludeRe.test(rel))) {
        uris.push(Uri.file(filePath));
      }
    }
    return uris;
  },
  openTextDocument: async (uriOrPath) => {
    const uri = typeof uriOrPath === 'string' ? Uri.file(uriOrPath) : uriOrPath;
    const existing = workspace.textDocuments.find((d) => d.uri.fsPath === uri.fsPath);
    if (existing) return existing;
    const text = await fs.promises.readFile(uri.fsPath, 'utf8');
    return createMockTextDocument(uri, text);
  },
  createFileSystemWatcher: () => {
    const createEmitter = new EventEmitter();
    const changeEmitter = new EventEmitter();
    const deleteEmitter = new EventEmitter();
    return {
      onDidCreate: createEmitter.event,
      onDidChange: changeEmitter.event,
      onDidDelete: deleteEmitter.event,
      dispose: () => {
        createEmitter.dispose();
        changeEmitter.dispose();
        deleteEmitter.dispose();
      },
    };
  },
  getConfiguration: (section = '', scope = undefined) => {
    const langPrefix =
      scope && typeof scope === 'object' && 'languageId' in scope && scope.languageId
        ? `[${scope.languageId}].`
        : '';
    const resolveKey = (key, overrideInLanguage = false) => {
      const base = section ? `${section}.${key}` : key;
      return overrideInLanguage && langPrefix ? `${langPrefix}${base}` : base;
    };
    return {
      get: (key, defaultValue) => {
        const langKey = resolveKey(key, true);
        if (langPrefix && configStore.has(langKey)) return configStore.get(langKey);
        const fullKey = resolveKey(key, false);
        return configStore.has(fullKey) ? configStore.get(fullKey) : defaultValue;
      },
      has: (key) =>
        (langPrefix ? configStore.has(resolveKey(key, true)) : false) ||
        configStore.has(resolveKey(key, false)),
      inspect: (key) => {
        const fullKey = resolveKey(key, false);
        const langKey = resolveKey(key, true);
        return {
          key: fullKey,
          globalValue: configStore.get(fullKey),
          globalLanguageValue: langPrefix ? configStore.get(langKey) : undefined,
        };
      },
      update: async (key, value, _target, overrideInLanguage = false) => {
        const storeKey = resolveKey(key, Boolean(overrideInLanguage));
        if (value === undefined) {
          configStore.delete(storeKey);
        } else {
          configStore.set(storeKey, value);
        }
      },
    };
  },
  applyEdit: async (edit) => {
    for (const op of edit.getFileOperations?.() ?? []) {
      if (op.type === 'rename') {
        await fs.promises.mkdir(path.dirname(op.newUri.fsPath), { recursive: true });
        await fs.promises.rename(op.oldUri.fsPath, op.newUri.fsPath);
      } else if (op.type === 'delete') {
        await fs.promises.rm(op.uri.fsPath, { recursive: Boolean(op.options?.recursive), force: true });
      } else if (op.type === 'create') {
        await fs.promises.mkdir(path.dirname(op.uri.fsPath), { recursive: true });
        if (op.options?.overwrite || !fs.existsSync(op.uri.fsPath)) {
          await fs.promises.writeFile(op.uri.fsPath, '');
        }
      }
    }
    for (const [uri, edits] of edit.entries()) {
      const doc = await workspace.openTextDocument(uri);
      let content = doc.getText();
      const sorted = [...edits].sort((a, b) => doc.offsetAt(b.range.start) - doc.offsetAt(a.range.start));
      for (const te of sorted) {
        const start = doc.offsetAt(te.range.start);
        const end = doc.offsetAt(te.range.end);
        content = content.slice(0, start) + te.newText + content.slice(end);
      }
      await fs.promises.writeFile(uri.fsPath, content, 'utf8');
    }
    return true;
  },
  onDidChangeConfiguration: mockEmitters.onDidChangeConfiguration.event,
  onDidCreateFiles: mockEmitters.onDidCreateFiles.event,
  onDidDeleteFiles: mockEmitters.onDidDeleteFiles.event,
  onDidRenameFiles: mockEmitters.onDidRenameFiles.event,
  onWillCreateFiles: mockEmitters.onWillCreateFiles.event,
  onWillDeleteFiles: mockEmitters.onWillDeleteFiles.event,
  onWillRenameFiles: mockEmitters.onWillRenameFiles.event,
  onDidSaveTextDocument: mockEmitters.onDidSaveTextDocument.event,
  onDidChangeTextDocument: mockEmitters.onDidChangeTextDocument.event,
  onDidOpenTextDocument: mockEmitters.onDidOpenTextDocument.event,
  onDidCloseTextDocument: mockEmitters.onDidCloseTextDocument.event,
};

export const window = {
  activeTextEditor: undefined,
  get visibleTextEditors() {
    return window.activeTextEditor ? [window.activeTextEditor] : [];
  },
  onDidChangeActiveTextEditor: mockEmitters.onDidChangeActiveTextEditor.event,
  onDidChangeVisibleTextEditors: mockEmitters.onDidChangeVisibleTextEditors.event,
  onDidChangeTextEditorSelection: mockEmitters.onDidChangeTextEditorSelection.event,
  showInformationMessage: async () => undefined,
  showWarningMessage: async () => undefined,
  showErrorMessage: async () => undefined,
  showQuickPick: async (items) => {
    const resolved = await items;
    return Array.isArray(resolved) ? resolved[0] : undefined;
  },
  showTextDocument: async (docOrUri, options) => {
    const doc = 'getText' in docOrUri ? docOrUri : await workspace.openTextDocument(docOrUri);
    const editor = {
      document: doc,
      selection: options?.selection ? new Selection(options.selection.start, options.selection.end) : new Selection(new Position(0, 0), new Position(0, 0)),
      revealRange: () => {},
      setDecorations: () => {},
    };
    window.activeTextEditor = editor;
    return editor;
  },
  createTextEditorDecorationType: (options = {}) => ({
    key: `mock-decoration-${Math.random().toString(36).slice(2)}`,
    options,
    dispose() {},
  }),
  createOutputChannel: (name) => ({
    name,
    lines: [],
    append: () => {},
    appendLine: (line) => {},
    clear: () => {},
    show: () => {},
    dispose: () => {},
  }),
  createStatusBarItem: (alignment = StatusBarAlignment.Left, priority = 0) => ({
    alignment,
    priority,
    text: '',
    tooltip: '',
    command: undefined,
    visible: false,
    show() { this.visible = true; },
    hide() { this.visible = false; },
    dispose() {},
  }),
  registerTreeDataProvider: (viewId, provider) => {
    const entry = { type: 'treeview', selector: viewId, provider };
    registeredProviders.push(entry);
    return new Disposable(() => {
      const idx = registeredProviders.indexOf(entry);
      if (idx >= 0) registeredProviders.splice(idx, 1);
    });
  },
  createTreeView: (viewId, options) => {
    const entry = { type: 'treeview', selector: viewId, provider: options?.treeDataProvider };
    registeredProviders.push(entry);
    return {
      dispose: () => {
        const idx = registeredProviders.indexOf(entry);
        if (idx >= 0) registeredProviders.splice(idx, 1);
      },
    };
  },
};

